-- M1 semantic review: honest CURRENT_CONTEXT non-independent DEVOLVER. No authorizes publishing.
-- Source details and seven criteria per rule: sandbox/lf_contract_gate_test/nucleo_ci/m1_juicios_semanticos_v1.json
BEGIN;
DO $m1judge$
DECLARE item jsonb; code text; v_h text; v_j jsonb; v_out jsonb;
 v_legacy text; v_core text; v_versions text; v_apps text; v_deprec text; v_other_judges text;
 v_n integer:=0;
BEGIN
 SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.id),'')) INTO v_legacy FROM lf_ops.reglas t;
 SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.codigo),'')) INTO v_core FROM lf_ops.nucleo_reglas t;
 SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.regla,t.version),'')) INTO v_versions FROM lf_ops.nucleo_regla_versiones t;
 SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.regla,t.nodo),'')) INTO v_apps FROM lf_ops.nucleo_aplicaciones t;
 SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.regla,t.version),'')) INTO v_deprec FROM lf_ops.nucleo_deprecaciones t;
 SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.id),'')) INTO v_other_judges FROM lf_ops.nucleo_juicios t WHERE t.regla NOT LIKE 'M1-C0%';
 FOR item IN SELECT value FROM jsonb_array_elements($reviews$[{"codigo":"M1-C01","fuente":"REG_CHK_001 / lf_ops.reglas/155","hallazgos":["La condición booleana no verifica que haya un único resumen ni el detalle separado por modalidad y oferta; únicamente confirma un indicador precalculado.","La legada REG_CHK_001 permanece VIGENTE bajo convivencia, sin acreditación de equivalencia completa."],"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"BLOQUEAR impide presentar como correcto un resumen discordante."},"CAL_ALCANCE":{"puntaje":1,"observacion":"CLIENT_PAYMENTS limita el análisis al módulo de pagos y checkout."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto especifica consolidación de ofertas, modalidades y preservación de selección."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR corresponde al guard de presentación discrepante."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"El hecho corresponde_seleccion no prueba unicidad del resumen ni detalle por oferta y modalidad."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"No introduce cifra de comisión; D01 y cálculo de REG_CHK_002 quedan separados."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Solapa contenido con REG_CHK_001 vigente por convivencia, sin prueba de absorción exacta."}},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica M1 en contexto actual (no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"BLOQUEAR impide presentar como correcto un resumen discordante."},"CAL_ALCANCE":{"puntaje":1,"observacion":"CLIENT_PAYMENTS limita el análisis al módulo de pagos y checkout."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto especifica consolidación de ofertas, modalidades y preservación de selección."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR corresponde al guard de presentación discrepante."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"El hecho corresponde_seleccion no prueba unicidad del resumen ni detalle por oferta y modalidad."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"No introduce cifra de comisión; D01 y cálculo de REG_CHK_002 quedan separados."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Solapa contenido con REG_CHK_001 vigente por convivencia, sin prueba de absorción exacta."}}}},{"codigo":"M1-C02","fuente":"REG_CHK_014 / 277 y REG_CHK_CUO_006 / 289","hallazgos":["La condición comprueba un indicador de cancelación, pero no representa canal Mis operaciones, visibilidad previa ni tratamiento de la carta de no adeudo.","El alcance BACKEND no satisface por sí solo la obligación visible en checkout; la conciliación de saldos y recurrencia requiere fuente técnica aún no entregada."],"puntajes":{"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"Bloquear rechazo improcedente de cancelación es útil, pero no demuestra ejecución del cambio ni aviso UI."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"BACKEND cubre la operación interna; checkout y Mis operaciones son superficies separadas pendientes."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El texto distingue cancelar cobro recurrente y mantener deuda exigible."},"COH_EFECTO":{"puntaje":0.5,"observacion":"BLOQUEAR expresa impedir rechazo indebido, no garantiza cancelación disponible y ejecutada."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Solo compara bandera sintética; no valida canal, estado de plan, penalidad efectiva ni aviso previo."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Respeta que cancelar el cobro recurrente no liquida deuda ni habilita carta anticipada."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Hay coincidencia funcional con dos legadas vigentes; falta demostrar absorción y alcance UI."}},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica M1 en contexto actual (no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"Bloquear rechazo improcedente de cancelación es útil, pero no demuestra ejecución del cambio ni aviso UI."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"BACKEND cubre la operación interna; checkout y Mis operaciones son superficies separadas pendientes."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El texto distingue cancelar cobro recurrente y mantener deuda exigible."},"COH_EFECTO":{"puntaje":0.5,"observacion":"BLOQUEAR expresa impedir rechazo indebido, no garantiza cancelación disponible y ejecutada."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Solo compara bandera sintética; no valida canal, estado de plan, penalidad efectiva ni aviso previo."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Respeta que cancelar el cobro recurrente no liquida deuda ni habilita carta anticipada."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Hay coincidencia funcional con dos legadas vigentes; falta demostrar absorción y alcance UI."}}}},{"codigo":"M1-C03","fuente":"REG_CLIENT_PAYMENT_RECEIPT_REAL_EMAIL_001 / 13126 (legada CANDIDATO)","hallazgos":["Bloqueo en BACKEND carece de un guard de intención de emisión de recibo; estado de pago pendiente activaría BLOQUEAR incluso en otras operaciones backend.","No comprueba source/customer_email validado, entrega, incidencia ni separación del correo técnico; la fuente legada sigue CANDIDATO y no autoriza producción.","El literal PAYMENT_CONFIRMED genera aviso no bloqueante de texto fijo en el proponente; requiere lista del vocabulario o respaldo."],"puntajes":{"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"Evitar recibos sin confirmación es correcto, pero un bloqueo global de BACKEND sería dañino."},"CAL_ALCANCE":{"puntaje":0,"observacion":"La condición no contiene guard 'emitir recibo'; BACKEND abarca otros procesos distintos."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto distingue correo real validado, Niubiz técnico e incidencia."},"COH_EFECTO":{"puntaje":0.5,"observacion":"BLOQUEAR corresponde a recibo, pero la condición no restringe su disparo a ese evento."},"COH_TEXTO_CONDICION":{"puntaje":0,"observacion":"Falta guard de emisión, verificación del destinatario y ruta de incidencia; los hechos no prueban todos los efectos declarados."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"Puede bloquear pagos normales no confirmados aunque no se solicite emitir recibo."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Existe fuente legada CANDIDATO 13126 con contenido equivalente parcial, sin homologación completa."}},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica M1 en contexto actual (no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"Evitar recibos sin confirmación es correcto, pero un bloqueo global de BACKEND sería dañino."},"CAL_ALCANCE":{"puntaje":0,"observacion":"La condición no contiene guard 'emitir recibo'; BACKEND abarca otros procesos distintos."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto distingue correo real validado, Niubiz técnico e incidencia."},"COH_EFECTO":{"puntaje":0.5,"observacion":"BLOQUEAR corresponde a recibo, pero la condición no restringe su disparo a ese evento."},"COH_TEXTO_CONDICION":{"puntaje":0,"observacion":"Falta guard de emisión, verificación del destinatario y ruta de incidencia; los hechos no prueban todos los efectos declarados."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"Puede bloquear pagos normales no confirmados aunque no se solicite emitir recibo."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Existe fuente legada CANDIDATO 13126 con contenido equivalente parcial, sin homologación completa."}}}},{"codigo":"M1-C04","fuente":"REG_NIU_005 / 229","hallazgos":["Los booleanos sandbox_certificado y credenciales_separadas carecen de fuente/procedimiento de certificación observado; no acreditan prueba integral real.","La obligación de separación de ambientes debe verificarse con evidencia del adaptador y no solo con estado calculado."],"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"Bloquea activación de checkout si faltan condiciones previas declaradas."},"CAL_ALCANCE":{"puntaje":1,"observacion":"BACKEND con guard habilitacion_produccion_pago acota el caso de uso."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Separa sandbox Niubiz, producción y credenciales."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR coincide con prohibir activación sin certificación previa."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Condición usa evidencias booleanas sin verificar pruebas integrales ni distinción real de credenciales."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Consistente con obligación legada 229, sin habilitar producción ni mezclar credenciales."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Replica núcleo preventivo de REG_NIU_005 vigente; absorción no certificada."}},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica M1 en contexto actual (no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"Bloquea activación de checkout si faltan condiciones previas declaradas."},"CAL_ALCANCE":{"puntaje":1,"observacion":"BACKEND con guard habilitacion_produccion_pago acota el caso de uso."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Separa sandbox Niubiz, producción y credenciales."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR coincide con prohibir activación sin certificación previa."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Condición usa evidencias booleanas sin verificar pruebas integrales ni distinción real de credenciales."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Consistente con obligación legada 229, sin habilitar producción ni mezclar credenciales."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Replica núcleo preventivo de REG_NIU_005 vigente; absorción no certificada."}}}},{"codigo":"M1-C05","fuente":"REG_TEC_007 / 183","hallazgos":["La condición solo observa desconexión en captura inicial; no exige persistencia local comprobable ni el banner literal aprobado.","El texto omite literalmente «Sin conexión. Tus datos están guardados.» y el alcance CLIENT_ONBOARDING no demuestra mapeo exacto PANTALLA-1 y PANTALLA-2."],"puntajes":{"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"EXIGIR en offline no identifica la acción técnica verificable ni el contenido exacto a mostrar."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"CLIENT_ONBOARDING más indicador de paso no acredita selección real de las dos pantallas."},"CAL_CLARIDAD":{"puntaje":0.5,"observacion":"Explica intención, pero omite texto literal del banner y prueba de conservación de datos."},"COH_EFECTO":{"puntaje":0.5,"observacion":"EXIGIR expresa obligación genérica, sin precisar guardado y señal al usuario."},"COH_TEXTO_CONDICION":{"puntaje":0,"observacion":"Detectar offline no demuestra datos preservados ni aviso presentado; faltan ambos efectos."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"No altera el bloqueo de pagos offline ya recogido por REG_TEC_007 V2."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Absorción parcial de REG_TEC_007 vigente; no se certifica reemplazo funcional."}},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica M1 en contexto actual (no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"EXIGIR en offline no identifica la acción técnica verificable ni el contenido exacto a mostrar."},"CAL_ALCANCE":{"puntaje":0.5,"observacion":"CLIENT_ONBOARDING más indicador de paso no acredita selección real de las dos pantallas."},"CAL_CLARIDAD":{"puntaje":0.5,"observacion":"Explica intención, pero omite texto literal del banner y prueba de conservación de datos."},"COH_EFECTO":{"puntaje":0.5,"observacion":"EXIGIR expresa obligación genérica, sin precisar guardado y señal al usuario."},"COH_TEXTO_CONDICION":{"puntaje":0,"observacion":"Detectar offline no demuestra datos preservados ni aviso presentado; faltan ambos efectos."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"No altera el bloqueo de pagos offline ya recogido por REG_TEC_007 V2."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Absorción parcial de REG_TEC_007 vigente; no se certifica reemplazo funcional."}}}},{"codigo":"M1-C06","fuente":"REG_TEC_009 / 185","hallazgos":["La condición valida repetición equivalente y plazo, pero no representa explícitamente identidad del usuario, idempotency_key, request_sha256 ni operation_number; tampoco verifica devolución de la misma respuesta.","La generación UUID v4 y envío X-Idempotency-Key siguen documentados, no evaluados en la condición; el borde exacto exige tratamiento sin segundo submit."],"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"PERMITIR representa reutilización de respuesta en reenvío equivalente dentro de ventana."},"CAL_ALCANCE":{"puntaje":1,"observacion":"BACKEND queda acotado con m1_operacion_submit_onboarding_inicial, sin actuar sobre checkout."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto explica reenvíos, ventana parametrizada y ausencia de duplicados."},"COH_EFECTO":{"puntaje":1,"observacion":"PERMITIR es coherente con reutilizar resultado anterior y no ejecutar otro cargo."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"No comprueba identidad/reserva ni recuperación real del resultado; el borde sin duplicado no queda modelado."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Respeta la ventana AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES y no cambia checkout."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Solapa REG_TEC_009 vigente y candidata de checkout; acota onboarding, falta demostrar alcance exacto."}},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica M1 en contexto actual (no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"PERMITIR representa reutilización de respuesta en reenvío equivalente dentro de ventana."},"CAL_ALCANCE":{"puntaje":1,"observacion":"BACKEND queda acotado con m1_operacion_submit_onboarding_inicial, sin actuar sobre checkout."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto explica reenvíos, ventana parametrizada y ausencia de duplicados."},"COH_EFECTO":{"puntaje":1,"observacion":"PERMITIR es coherente con reutilizar resultado anterior y no ejecutar otro cargo."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"No comprueba identidad/reserva ni recuperación real del resultado; el borde sin duplicado no queda modelado."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Respeta la ventana AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES y no cambia checkout."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Solapa REG_TEC_009 vigente y candidata de checkout; acota onboarding, falta demostrar alcance exacto."}}}}]$reviews$::jsonb) LOOP
  code:=item->>'codigo';
  IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas r JOIN lf_ops.nucleo_regla_versiones v ON v.regla=r.codigo
     WHERE r.codigo=code AND r.estado='CANDIDATA' AND v.version=1 AND v.estado='CANDIDATA' AND v.publicada_desde IS NULL AND v.exigible_desde IS NULL)
  THEN RAISE EXCEPTION 'M1_JUDGE_SOURCE_NOT_CANDIDATE %',code; END IF;
  IF EXISTS(SELECT 1 FROM lf_ops.nucleo_juicios WHERE regla=code AND version=1)
  THEN RAISE EXCEPTION 'M1_JUDGE_ALREADY_RECORDED %',code; END IF;
  v_h:=lf_ops.nucleo_hash_paquete_v1(code,1);
  v_j:=(item->'juicio')||jsonb_build_object('regla',code,'hash_evaluado',v_h,
    'evidencia_ref','https://github.com/cristhianlujan/claude-persona-lf-patch/blob/main/sandbox/lf_contract_gate_test/nucleo_ci/m1_juicios_semanticos_v1.json#'||code);
  IF v_j->>'modo'<>'CONTEXTO_ACTUAL' OR v_j->>'veredicto'<>'DEVOLVER'
    OR v_j->>'revisor_es_productor'<>'true' OR v_j->>'llamadas_modelo'<>'0'
    OR (SELECT count(*) FROM jsonb_object_keys(v_j->'puntajes'))<>7
    OR (SELECT count(*) FROM lf_ops.nucleo_rubrica WHERE estado='ACTIVO')<>7
  THEN RAISE EXCEPTION 'M1_JUDGE_PROVENANCE_OR_RUBRIC_DRIFT %',code; END IF;
  BEGIN
   PERFORM lf_ops.nucleo_juicio_registrar_v1(v_j||jsonb_build_object('hash_evaluado',repeat('0',64)));
   RAISE EXCEPTION 'M1_JUDGE_BAD_HASH_ACCEPTED %',code;
  EXCEPTION WHEN others THEN
   IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF;
  END;
  BEGIN
   PERFORM lf_ops.nucleo_juicio_registrar_v1(v_j||jsonb_build_object('puntajes',(v_j->'puntajes')-'SEM_NO_DUPLICA'));
   RAISE EXCEPTION 'M1_JUDGE_INCOMPLETE_RUBRIC_ACCEPTED %',code;
  EXCEPTION WHEN others THEN
   IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_RUBRICA_INCOMPLETA:%' THEN RAISE; END IF;
  END;
  PERFORM lf_ops.nucleo_juicio_registrar_v1(v_j);
  v_out:=lf_ops.nucleo_regla_evaluar_v1(code,true);
  IF v_out->>'decision'<>'DEVUELTA'
    OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_out->'motivos') x WHERE x->>'dimension'='JUEZ')
    OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_juicios j WHERE j.regla=code AND j.version=1 AND j.hash_evaluado=v_h
                  AND j.veredicto='DEVOLVER' AND j.modo='CONTEXTO_ACTUAL' AND j.revisor_es_productor IS TRUE
                  AND j.llamadas_modelo=0)
  THEN RAISE EXCEPTION 'M1_JUDGE_UNSAFE_VERDICT % %',code,v_out; END IF;
  IF (SELECT estado FROM lf_ops.nucleo_reglas WHERE codigo=code)<>'CANDIDATA'
    OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=1)<>'CANDIDATA'
  THEN RAISE EXCEPTION 'M1_JUDGE_CHANGED_PUBLICATION %',code; END IF;
  RAISE NOTICE 'M1_JUDGE_RESULT %', jsonb_build_object('codigo',code,'hash',v_h,'veredicto','DEVOLVER','decision',v_out->>'decision','nota',v_out->'nota','modo','CONTEXTO_ACTUAL','llamadas_modelo',0);
  v_n:=v_n+1;
 END LOOP;
 IF v_n<>6
    OR (SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.id),'')) FROM lf_ops.reglas t) IS DISTINCT FROM v_legacy
    OR (SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.codigo),'')) FROM lf_ops.nucleo_reglas t) IS DISTINCT FROM v_core
    OR (SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.regla,t.version),'')) FROM lf_ops.nucleo_regla_versiones t) IS DISTINCT FROM v_versions
    OR (SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.regla,t.nodo),'')) FROM lf_ops.nucleo_aplicaciones t) IS DISTINCT FROM v_apps
    OR (SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.regla,t.version),'')) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM v_deprec
    OR (SELECT md5(coalesce(string_agg(to_jsonb(t)::text,'|' ORDER BY t.id),'')) FROM lf_ops.nucleo_juicios t WHERE t.regla NOT LIKE 'M1-C0%') IS DISTINCT FROM v_other_judges
    OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE regla LIKE 'M1-C0%' AND version=1)<>6
    OR EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo LIKE 'M1-C0%' AND estado<>'CANDIDATA')
    OR EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'M1-C0%' AND estado<>'CANDIDATA')
 THEN RAISE EXCEPTION 'M1_JUDGE_FINAL_READBACK_DRIFT'; END IF;
 RAISE NOTICE 'M1_JUDGE_PASS 6/6 DEVOLVER CONTEXTO_ACTUAL; 12/12 negatives rejected; 0 published; legacy/core unchanged';
END $m1judge$;
COMMIT;
